import { Inject } from '@nestjs/common';
import { getDataSourceToken, getEntityManagerToken, getRepositoryToken, } from './typeorm.utils.js';
/**
 * @publicApi
 */
export const InjectRepository = (entity, dataSource) => Inject(getRepositoryToken(entity, dataSource));
/**
 * @publicApi
 */
export const InjectDataSource = (dataSource) => Inject(getDataSourceToken(dataSource));
/** @deprecated */
export const InjectConnection = InjectDataSource;
/**
 * @publicApi
 */
export const InjectEntityManager = (dataSource) => Inject(getEntityManagerToken(dataSource));
